(933947, 108233, 17233, '<td valign="top">Great action shot. Nice colour saturation and sharpness. (8)</td>', 'Great action shot. Nice colour saturation and sharpness. (8)', '2004-10-01 06:46:41.000000', NULL, 1),
(933951, 109008, 17233, '<td valign="top">Magnificent colours and composition. Contrast also very good and the direction of the light shows up the texture of the feathers very well. (8)</td>', 'Magnificent colours and composition. Contrast also very good and the direction of the light shows up the texture of the feathers very well. (8)', '2004-10-01 06:51:37.000000', NULL, 1),
