(935605, 108991, 5112, '<td valign="top">Nice.  Love the peachy glow on the water and in the sky.</td>', 'Nice.  Love the peachy glow on the water and in the sky.', '2004-10-01 19:47:56.000000', NULL, 1),
(935606, 108843, 5112, '<td valign="top">Very peaceful.  Good job.</td>', 'Very peaceful.  Good job.', '2004-10-01 19:48:24.000000', NULL, 1),
