(935624, 108992, 4536, '<td valign="top">The horizon is a bit tilted, otherwise a nice composition. Seems dark though.</td>', 'The horizon is a bit tilted, otherwise a nice composition. Seems dark though.', '2004-10-01 20:01:47.000000', NULL, 1),
(935627, 107397, 20941, '<td valign="top">Great job recognizing a subject and capturing something forgotten and making it memorable</td>', 'Great job recognizing a subject and capturing something forgotten and making it memorable', '2004-10-01 20:03:24.000000', NULL, 1),
(935628, 103105, 17851, '<td valign="top">Over all this photograph is amazing!...your lighting, composition, and emotion are perfect, a beautiful image.  Good luck, my pick for the Blue</td>', 'Over all this photograph is amazing!...your lighting, composition, and emotion are perfect, a beautiful image.  Good luck, my pick for the Blue', '2004-10-01 20:03:34.000000', NULL, 1),
(935629, 108872, 4536, '<td valign="top">Oooo, nice colors and composition. Needs a bit more (an added element or surprise) for a ribbon, but could see this hanging on someones wall.</td>', 'Oooo, nice colors and composition. Needs a bit more (an added element or surprise) for a ribbon, but could see this hanging on someones wall.', '2004-10-01 20:03:37.000000', NULL, 1),
(935631, 107365, 4536, '<td valign="top">Indeed! Nice reflection, good composition. He does seem rather small though for the title, not sure how I can tell this without something to judge his size by. Perhaps cloning out the spot would have been a good idea.</td>', 'Indeed! Nice reflection, good composition. He does seem rather small though for the title, not sure how I can tell this without something to judge his size by. Perhaps cloning out the spot would have been a good idea.', '2004-10-01 20:06:00.000000', NULL, 1),
