(935641, 107995, 4536, '<td valign="top">Bravo if this was an original idea, very clever. Nice lighting too.</td>', 'Bravo if this was an original idea, very clever. Nice lighting too.', '2004-10-01 20:11:49.000000', NULL, 1),
(935642, 108872, 20941, '<td valign="top">I love it!</td>', 'I love it!', '2004-10-01 20:12:29.000000', NULL, 1),
