(938630, 104134, 8139, '<td valign="top">Gorgeous portraiture. Attracting eyes.</td>', 'Gorgeous portraiture. Attracting eyes.', '2004-10-03 14:18:46.000000', NULL, 1),
(938633, 104030, 10686, '<td valign="top">Great postcard shot. -8</td>', 'Great postcard shot. -8', '2004-10-03 14:19:24.000000', NULL, 1),
(938635, 107901, 10686, '<td valign="top">Nice one Jacko -9</td>', 'Nice one Jacko -9', '2004-10-03 14:20:00.000000', NULL, 1),
(938637, 107397, 17033, '<td valign="top">Really like both the content and style of this photo. I''m assuming it''s Neatimaged which, in the right circumstances, like these, can really add to the atmosphere.</td>', 'Really like both the content and style of this photo. I''m assuming it''s Neatimaged which, in the right circumstances, like these, can really add to the atmosphere.', '2004-10-03 14:21:41.000000', NULL, 1),
