(942215, 108537, 10263, '<td valign="top">Love the soft look. The black and white works well here.</td>', 'Love the soft look. The black and white works well here.', '2004-10-05 00:22:53.000000', NULL, 1),
(942217, 103619, 20662, '<td valign="top">Can''t wait to see how you did this! Good Luck</td>', 'Can''t wait to see how you did this! Good Luck', '2004-10-05 00:22:57.000000', NULL, 1),
(942218, 107902, 22239, '<td valign="top">Great colors on this one... really invites that retro feel.  Looks awfully smooth, though, almost computer-generated.  Usually, over-smoothing really detracts from an image, but here, it seems to work well with the almost pastel colors and the subject matter.</td>', 'Great colors on this one... really invites that retro feel.  Looks awfully smooth, though, almost computer-generated.  Usually, over-smoothing really detracts from an image, but here, it seems to work well with the almost pastel colors and the subject matter.', '2004-10-05 00:23:24.000000', NULL, 1),
(942219, 107397, 23203, '<td valign="top">A captivating image.. wish I could make this my desktop!<br/></td>', 'A captivating image.. wish I could make this my desktop!', '2004-10-05 00:23:41.000000', NULL, 1),
(942221, 108173, 23203, '<td valign="top">Jacko?</td>', 'Jacko?', '2004-10-05 00:24:08.000000', NULL, 1),
