(948757, 107969, 6532, '<td valign="top">I knew that most people probably are raving about this photo and do not get me wrong it is a nice pic.  But, it lacks appeal for me.  The hint of blue in the background is distracting.</td>', 'I knew that most people probably are raving about this photo and do not get me wrong it is a nice pic.  But, it lacks appeal for me.  The hint of blue in the background is distracting.', '2004-10-07 18:00:27.000000', NULL, 1),
(948758, 103105, 6532, '<td valign="top">Seems a bit too dark.</td>', 'Seems a bit too dark.', '2004-10-07 18:01:02.000000', NULL, 1),
(948760, 103788, 23226, '<td valign="top">Awesome picture. It sets a great mood.</td>', 'Awesome picture. It sets a great mood.', '2004-10-07 18:01:20.000000', NULL, 1),
(948762, 107397, 23226, '<td valign="top">Beautiful picture.</td>', 'Beautiful picture.', '2004-10-07 18:01:42.000000', NULL, 1),
