(948766, 107609, 23226, '<td valign="top">Incredible lighting. Great picture.</td>', 'Incredible lighting. Great picture.', '2004-10-07 18:02:44.000000', NULL, 1),
(948767, 107902, 6532, '<td valign="top">I like the colors in this.  But to me, the flat appearance takes away from the overall.</td>', 'I like the colors in this.  But to me, the flat appearance takes away from the overall.', '2004-10-07 18:02:50.000000', NULL, 1),
